Object.assign(window.TEM8_DICTIONARY, {"uphill":{"media":{"uk":"media/uk/uphill__gb_1.mp3","us":"media/us/uphill__us_1.mp3"},"oxford":{"phon":"ˌʌpˈhɪl","pos":"adjective","senses":[{"en":"sloping upwards","cn":"上坡的","ex":{"en":"an uphill climb/slope","cn":"向上的攀爬；上坡"}},{"en":"an argument or a struggle that is difficult to win and takes a lot of effort over a long period of time","cn":"漫长而艰难的，费力的（战斗、斗争、任务等）","ex":{"en":"He faces an uphill struggle to be fit in time for the championships.","cn":"为了及时适应锦标赛，他面临着一场艰苦的斗争。"}},{"en":"towards the top of a hill or slope","cn":"向山上；朝上坡方向","ex":{"en":"We cycled uphill for over an hour.","cn":"我们骑自行车爬了一个多小时的坡。"},"pos":"adverb"}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"靠山顶；上坡","en":"If something or someone is uphill or is moving uphill, they are near the top of a hill or are going up a slope.","ex":{"en":"He had been running uphill a long way","cn":"他已经跑了一段很长的上坡路。"}},{"pos":"ADJ 形容词","cn":"荆棘满途的；艰苦卓绝的；崎岖曲折的","en":"If you refer to something as an uphill struggle or an uphill battle, you mean that it requires a great deal of effort and determination, but it should be possible to achieve it.","ex":{"en":"It had been an uphill struggle to achieve what she had wanted","cn":"她历尽坎坷才达到目的。"}}]},"examples":[{"en":"We cycled uphill for over an hour.","cn":"我们骑自行车爬了一个多小时的坡。"},{"en":"The last part of the race is all uphill.","cn":"赛跑的最后一段全是上坡路。"}]},"upright":{"media":{"uk":"media/uk/upright__gb_1.mp3","us":"media/us/upright__us_1.mp3"},"oxford":{"phon":"ˈʌpraɪt","pos":"adjective","senses":[{"en":"not lying down, and with the back straight rather than bent","cn":"直立的；挺直的","ex":{"en":"Try to maintain an upright posture while doing this exercise.","cn":"进行此练习时尽量保持直立姿势。"}},{"en":"placed in a vertical position","cn":"竖直的；直立的；垂直的","ex":{"en":"Keep the bottle upright.","cn":"保持瓶子直立。"}},{"en":"behaving in a moral and honest way","cn":"正直的；正派的；诚实的","ex":{"en":"an upright citizen","cn":"正直的公民"}},{"en":"in or into a straight, vertical position","cn":"竖立着；垂直着","ex":{"en":"She sat upright in bed.","cn":"她挺直地坐在床上。"},"pos":"adverb"},{"en":"a long piece of wood, metal or plastic that is placed in a vertical position, especially in order to support something","cn":"（尤指支撑用的）直柱，立柱，立放构件","pos":"noun"},{"en":"a piano in which the strings are vertical (= go straight up and down)","cn":"立式钢琴","pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"垂直的；挺直的；直挺挺的","en":"If you are sitting or standing upright, you are sitting or standing with your back straight, rather than bending or lying down.","ex":{"en":"Helen sat upright in her chair","cn":"海伦笔直地坐在椅子上。"}},{"pos":"ADJ 形容词","cn":"（吸尘器、冰箱等）竖式的，立式的","en":"An upright vacuum cleaner or freezer is tall rather than wide.","ex":{"en":"...the latest state-of-the-art upright vacuum cleaners.","cn":"最新款、最先进的立式吸尘器"}},{"pos":"ADJ 形容词","cn":"（椅子）直靠背的，没有扶手的","en":"An upright chair has a straight back and no arms.","ex":{"en":"He was sitting on an upright chair beside his bed, reading.","cn":"他正坐在床前一张直背椅上看书。"}},{"pos":"N-COUNT 可数名词","cn":"立柱；立放构件","en":"You can refer to vertical posts or the vertical parts of an object as uprights .","ex":{"en":"...the uprights of a four-poster bed.","cn":"四柱床的立柱"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"诚实的，正直的；规矩的","en":"You can describe people as upright when they are careful to follow acceptable rules of behaviour and behave in a moral way.","ex":{"en":"...a very upright, trustworthy man.","cn":"一个非常正直可靠的人"}}]},"examples":[{"en":"Gradually raise your body into an upright position.","cn":"慢慢起身，成直立状态。"},{"en":"She sat upright in bed.","cn":"她挺直地坐在床上。"}]},"upstairs":{"media":{"uk":"media/uk/upstairs__gb_1.mp3","us":"media/us/upstairs__us_1.mp3"},"oxford":{"phon":"ˌʌpˈsteəz","pos":"adverb","senses":[{"en":"up the stairs; on or to a floor of a house or other building higher than the one that you are on","cn":"在（或向）楼上；在（或向）上一层","ex":{"en":"to run/walk/head upstairs","cn":"跑／走上楼；往楼上走"}},{"en":"on a floor of a house or other building that is higher than the one that you are on","cn":"在楼上的；在上一楼层的","ex":{"en":"an upstairs room/window/bathroom","cn":"楼上的房间/窗户/浴室"},"pos":"adjective"},{"en":"the floor or floors in a building that are above the ground floor","cn":"二楼；二楼以上各层；楼上","ex":{"en":"We've converted the upstairs into an office.","cn":"我们把楼上改成了办公室。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"上楼；往楼上","en":"If you go upstairs in a building, you go up a staircase towards a higher floor.","ex":{"en":"He went upstairs and changed into fresh clothes","cn":"他上楼换上干净衣服。"}},{"pos":"ADV 副词","cn":"在楼上","en":"If something or someone is upstairs in a building, they are on a floor that is higher than the ground floor.","ex":{"en":"The restaurant is upstairs and consists of a large, open room","cn":"饭店在楼上，有一个宽敞的开间。"}},{"pos":"ADJ 形容词","cn":"楼上的","en":"An upstairs room or object is situated on a floor of a building that is higher than the ground floor.","ex":{"en":"Marsani moved into the upstairs apartment.","cn":"马萨尼搬进了楼上的公寓里。"}},{"pos":"N-SING 单数名词","cn":"楼层","en":"The upstairs of a building is the floor or floors that are higher than the ground floor.","ex":{"en":"Together we went through the upstairs","cn":"我们一起走过各层楼。"}}]},"examples":[{"en":"We've converted the upstairs into an office.","cn":"我们把楼上改成了办公室。"},{"en":"I carried her bags upstairs.","cn":"我把她的包拿到楼上。"}]},"upward":{"media":{"uk":"media/uk/upward__gb_1.mp3","us":"media/us/upward__us_1.mp3"},"oxford":{"phon":"ˈʌpwəd","pos":"adjective","senses":[{"en":"pointing towards or facing a higher place","cn":"向上的；朝上的；向高处的","ex":{"en":"an upward gaze","cn":"举目凝望"}},{"en":"increasing in amount or price","cn":"（数量、价格）上升的，上涨的，增长的","ex":{"en":"an upward movement in property prices","cn":"房地产价格的上升"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"向上的","en":"An upward movement or look is directed towards a higher place or a higher level.","ex":{"en":"She started once again on the steep upward climb","cn":"她又开始沿着陡峭的山路往上爬。"}},{"pos":"ADJ 形容词","cn":"上升的；升高的","en":"If you refer to an upward trend or an upward spiral, you mean that something is increasing in quantity or price.","ex":{"en":"...the Army's concern that the upward trend in the numbers avoiding military service may continue","cn":"部队对逃避服兵役人数可能持续增多的担忧"}}]},"examples":[{"en":"an upward movement in property prices","cn":"房地产价格的上升"},{"en":"an upward gaze","cn":"举目凝望"}]},"upgrade":{"media":{"uk":"media/uk/upgrade__gb_1.mp3","us":"media/us/upgrade__us_1.mp3"},"oxford":{"phon":"ˌʌpˈɡreɪd","pos":"verb","senses":[{"en":"to make a machine, computer system, etc. more powerful and efficient; to start using a new and better version of a machine, system, etc.","cn":"升级，改进（机器、计算机系统等）；开始使用（升级版）","g":"[transitive, intransitive]","ex":{"en":"We are constantly upgrading our software to meet customers' needs.","cn":"我们不断升级软件以满足用户的需要。"}},{"en":"to improve the condition of a building, etc. in order to provide a better service","cn":"提高（设施、服务等的）档次；改善；使升格","g":"[transitive]","ex":{"en":"to upgrade the town’s leisure facilities","cn":"改善镇里的休闲设施"}},{"en":"to give somebody a better seat on a plane, room in a hotel, etc. than the one that they have paid for","cn":"升级（机票舱位、旅馆客房等）","g":"[transitive, often passive]","ex":{"en":"On the flight back, we were upgraded to business class.","cn":"返程时，我们升级到了公务舱。"}},{"en":"to give somebody a more important job","cn":"提升；提拔","g":"[transitive]"},{"en":"the act of making a machine, computer system, etc. more powerful and efficient; the more powerful and efficient machine, computer system, etc.","cn":"（机器、计算机系统等的）升级，升级版","ex":{"en":"instructions for installing an upgrade to the existing system","cn":"现有系统升级安装说明"},"pos":"noun"},{"en":"the act of improving the condition of a building, etc. in order to provide a better service","cn":"（设施、服务等的）提高档次，改善，升格","ex":{"en":"The building urgently needs an upgrade.","cn":"该建筑迫切需要升级。"},"pos":"noun"},{"en":"the act of giving somebody a better seat on a plane, room in a hotel, etc. than the one that they paid for; the seat, room, etc. itself","cn":"（舱位、旅馆房间等的）升级；升级的舱位（或房间等）","ex":{"en":"Frequent flyers qualify for a free upgrade.","cn":"常旅客有资格享受免费升舱。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"改良；更新；升级","en":"If equipment or services are upgraded, they are improved or made more efficient.","ex":{"en":"Helicopters have been upgraded and modernized","cn":"直升机已经更新换代，装配了现代化设备。"}},{"pos":"VERB 动词","cn":"擢升；晋升；提升；提拔","en":"If someone is upgraded, their job or status is changed so that they become more important or receive more money.","ex":{"en":"He was upgraded to security guard.","cn":"他被擢升为保安。"}},{"pos":"VERB 动词","cn":"(使)升级到更高待遇;(使)升舱","en":"If you upgrade or are upgraded, you change something such as your air ticket or your hotel room to one that is more expensive.","ex":{"en":"You can upgrade from self-catering accommodation to a hotel.","cn":"您可以将自理膳食旅店升级为酒店。"}}]},"examples":[{"en":"to upgrade the town's leisure facilities","cn":"改善镇里的休闲设施"},{"en":"You’ll need to upgrade your hard drive to 120Mb before running this software.","cn":"运行这个软件之前你需要把硬盘升级到120兆。"}]},"update":{"media":{"uk":"media/uk/update__gb_1.mp3","us":"media/us/update__us_1.mp3"},"oxford":{"phon":"ˌʌpˈdeɪt","pos":"verb","senses":[{"en":"to make something more modern by adding new parts, etc.","cn":"使现代化；更新","ex":{"en":"an updated version of the app","cn":"该应用的更新版"}},{"en":"to give somebody the most recent information about something; to add the most recent information to something","cn":"向…提供最新信息；给…增加最新信息","ex":{"en":"I'll be updating you shortly.","cn":"我很快就会向您通报最新情况。"}},{"en":"a report or broadcast that gives the most recent information about something; a new version of something containing the most recent information","cn":"最新报道；最新消息；最新进展","ex":{"en":"They will send you regular updates by email.","cn":"他们会发电邮定期告知你最新消息。"},"pos":"noun"},{"en":"the most recent improvements to a computer program that are sent to users of the program","cn":"（计算机程序的）更新，最新校正数据","lab":"computing","ex":{"en":"software updates","cn":"软件更新"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"更新；使现代化","en":"If you update something, you make it more modern, usually by adding new parts to it or giving new information.","ex":{"en":"He was back in the office, updating the work schedule on the computer","cn":"他已回到办公室，正在电脑上更新工作日程。"}},{"pos":"N-COUNT 可数名词","cn":"最新消息；快讯；速递","en":"An update is a news item containing the latest information about a particular situation.","ex":{"en":"She had heard the news-flash on a TV channel's news update.","cn":"她在一家电视台的新闻快讯中听到了这则简明新闻。"}},{"pos":"VERB 动词","cn":"为…提供最新消息；把最新进展告诉（某人）","en":"If you update someone on a situation, you tell them the latest developments in that situation.","ex":{"en":"We'll update you on the day's top news stories","cn":"我们将为您提供当天的重要新闻。"}}]},"examples":[{"en":"I called the office to update them on the day's developments.","cn":"我给办公室打电话告诉他们当天最新的发展。"},{"en":"It's about time we updated our software.","cn":"我们的软件应该更新了。"}]},"upbringing":{"oxford":{"phon":"ˈʌpbrɪŋɪŋ","pos":"noun","senses":[{"en":"the way in which a child is cared for and taught how to behave while it is growing up","cn":"抚育；养育；教养；培养","ex":{"en":"She had had a very sheltered upbringing.","cn":"她在备受呵护中长大。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"抚育；培育；养育；教养","en":"Your upbringing is the way that your parents treat you and the things that they teach you when you are growing up.","ex":{"en":"Martin's upbringing shaped his whole life","cn":"马丁的家庭教养影响了他的一生。"}}]},"media":{"uk":"media/uk/upbringing__gb_1.mp3","us":"media/us/upbringing__us_1.mp3"},"examples":[{"en":"He was a Catholic by upbringing.","cn":"他因受家庭薰陶，从小就是个天主教徒。"},{"en":"to have had a sheltered upbringing","cn":"受到呵护的养育"}]},"uptake":{"media":{"uk":"media/uk/uptake__gb_1.mp3","us":"media/us/uptake__us_1.mp3"},"oxford":{"phon":"ˈʌpteɪk","pos":"noun","senses":[{"en":"the use that is made of something that has become available","cn":"（对现有东西的）使用，利用，应用","ex":{"en":"There has been a high uptake of the free training.","cn":"免费培训有很多人参加。"}},{"en":"the process by which something is taken into a body or system; the rate at which this happens","cn":"吸收；吸收速度","lab":"specialist","ex":{"en":"the uptake of oxygen by muscles","cn":"肌肉对氧气的吸收"}}]},"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"摄入；摄取","en":"A person's uptake of something is the amount of it that they use.","ex":{"en":"The drug increases the number of red cells in the blood, enhancing oxygen uptake by 10 percent.","cn":"这种药增加了血液里的红细胞数量，从而将摄氧量提高了10%。"}},{"pos":"PHRASE 短语","cn":"理解力强/理解力弱","en":"You say that someone is quick on the uptake when they understand things quickly. You say that someone is slow on the uptake when they have difficulty understanding simple or obvious things.","ex":{"en":"She is not an intellectual, but is quick on the uptake","cn":"她并不是个才智非凡的人，但理解力很强。"}}]},"examples":[{"en":"There has been a high uptake of the free training.","cn":"免费培训有很多人参加。"},{"en":"Is he always this slow on the uptake?","cn":"他总是理解得这么慢吗？"}]},"upwards":{"media":{"uk":"media/uk/upwards__gb_1.mp3","us":"media/us/upwards__us_1.mp3"},"oxford":{"phon":"ˈʌpwədz","pos":"adverb","senses":[{"en":"towards a higher place or position","cn":"向上；向高处","ex":{"en":"Place your hands on the table with the palms facing upwards.","cn":"把手放在桌子上，手心朝上。"}},{"en":"towards a higher amount or price","cn":"（数量、价格）上升，上涨，提高","ex":{"en":"Bad weather forced the price of fruit upwards.","cn":"恶劣的天气迫使水果价格上涨。"}},{"en":"more than the amount or number mentioned","cn":"在…以上；大于；超过","ex":{"en":"You should expect to pay upwards of £50 for a hotel room.","cn":"酒店每个房间预计至少要 50 英镑。"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"向上","en":"If someone moves or looks upwards, they move or look up towards a higher place.","ex":{"en":"'There,' said Jack, pointing upwards","cn":"“在那里，”杰克向上指着说。"}},{"pos":"ADV 副词","cn":"上升；上涨","en":"If an amount or rate moves upwards, it increases.","ex":{"en":"...with prices soon heading upwards in high street stores","cn":"商业大街上商店里的价格迅速上涨"}},{"pos":"PREP-PHRASE 短语介词","cn":"…以上；多于…","en":"A quantity that is upwards of a particular number is more than that number.","ex":{"en":"...projects worth upwards of 200 million pounds","cn":"价值2亿多英镑的项目"}}]},"examples":[{"en":"You should expect to pay upwards of £50 for a hotel room.","cn":"住宿饭店，每个房间预计至少要 50 英镑。"},{"en":"Bad weather forced the price of fruit upwards.","cn":"恶劣的天气迫使水果价格上涨。"}]},"upset":{"oxford":{"phon":"ˌʌpˈset","pos":"adjective","senses":[{"en":"unhappy or disappointed because of something unpleasant that has happened","cn":"难过；不高兴；失望；沮丧","g":"[not before noun]","ex":{"en":"I understand how upset you must be feeling.","cn":"我理解你一定感到多么沮丧。"}},{"en":"an illness in the stomach that makes you feel sick (= want to vomit) or have diarrhoea","cn":"（肠胃）不适的；腹泻的","ex":{"en":"I've been off work with an upset stomach.","cn":"我因胃部不适而下班了。"}},{"en":"to make somebody/yourself feel unhappy, anxious or annoyed","cn":"使烦恼；使心烦意乱；使生气","ex":{"en":"This decision is likely to upset a lot of people.","cn":"这项决定很可能会使许多人不快。"},"pos":"verb"},{"en":"to make a plan, situation, etc. go wrong","cn":"打乱；搅乱","ex":{"en":"He arrived an hour late and upset all our arrangements.","cn":"他迟到了一个小时，把我们的一切安排都打乱了。"},"pos":"verb"},{"en":"to make somebody feel sick (= want to vomit) after they have eaten or drunk something","cn":"使（肠胃）不适","pos":"verb"},{"en":"to make something fall over by hitting it by accident","cn":"打翻；碰倒；使倾覆","ex":{"en":"She stood up suddenly, upsetting a glass of water.","cn":"她突然站了起来，打翻了一杯水。"},"pos":"verb"},{"en":"a situation in which there are problems or difficulties, especially when these are unexpected","cn":"（意外的）混乱，困扰，麻烦","g":"[uncountable]","ex":{"en":"The company has survived the recent upset in share prices.","cn":"这家公司撑过了最近股价的动荡。"},"pos":"noun"},{"en":"a situation in which a person or team beats the person or team that was expected to win","cn":"意外的结果；爆冷门","g":"[countable]","ex":{"en":"The biggest upset of the tournament came when the top seed was beaten in the second round.","cn":"本届赛事最大的冷门是头号种子在第二轮被击败。"},"pos":"noun"},{"en":"an illness in the stomach that makes you feel sick (= want to vomit) or have diarrhoea","cn":"（肠胃）不适的；腹泻的","g":"[countable]","ex":{"en":"a stomach upset","cn":"拉肚子"},"pos":"noun"},{"en":"the state of being unhappy, disappointed or worried because of something unpleasant that has happened","cn":"难过；不高兴；失望；沮丧","g":"[uncountable, countable]","ex":{"en":"It had been the cause of much emotional upset.","cn":"那便是使人情绪一落千丈的原因。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"心烦的；苦恼的；沮丧的","en":"If you are upset, you are unhappy or disappointed because something unpleasant has happened to you.","ex":{"en":"After she died I felt very, very upset","cn":"她去世之后，我非常非常难过。"}},{"pos":"VERB 动词","cn":"使心烦意乱；使生气；使心情不好","en":"If something upsets you, it makes you feel worried or unhappy.","ex":{"en":"The whole incident had upset me and my fiancee terribly","cn":"整个事件搞得我和未婚妻都心烦意乱。"}},{"pos":"VERB 动词","cn":"打乱；搅乱","en":"If events upset something such as a procedure or a state of affairs, they cause it to go wrong.","ex":{"en":"...a deal that would upset the balance of power in the world's gold markets","cn":"一桩将会打破全球黄金市场均势的交易"}},{"pos":"VERB 动词","cn":"弄翻；打翻；弄乱","en":"If you upset an object, you accidentally knock or push it over so that it scatters over a large area.","ex":{"en":"Don't upset the piles of sheets under the box.","cn":"不要把箱子下面那几叠床单弄乱了。"}},{"pos":"N-COUNT 可数名词","cn":"（肠胃的）不适","en":"A stomach upset is a slight illness in your stomach caused by an infection or by something that you have eaten.","ex":{"en":"Paul was unwell last night with a stomach upset","cn":"保罗昨晚肚子不舒服。"}},{"pos":"","cn":"","en":"to upset the applecart→see: ;"}]},"media":{"uk":"media/uk/upset__gb_1.mp3","us":"media/us/upset__us_1.mp3"},"examples":[{"en":"It upsets me to think of her all alone in that big house.","cn":"想到她孤身一人守着那所大房子，我就感到不舒服。"},{"en":"He arrived an hour late and upset all our arrangements.","cn":"他迟到了一个小时，把我们的一切安排都打乱了。"}]},"upper":{"media":{"uk":"media/uk/upper__gb_1.mp3","us":"media/us/upper__us_1.mp3","img":["media/ldoce/img/shoes.jpg"]},"oxford":{"phon":"ˈʌpə(r)","pos":"adjective","senses":[{"en":"located above something else, especially something of the same type or the other of a pair","cn":"上边的，上面的，上层的（尤指同类或一对中的一个）","ex":{"en":"her upper lip","cn":"她的上嘴唇"}},{"en":"at or near the top of something","cn":"上部的；靠上部的","ex":{"en":"There is an upper limit of £20 000 spent on any one project.","cn":"任何项目都有一个 2 万英镑的经费上限。"}},{"en":"located away from the coast, on high ground or towards the north of an area","cn":"内陆的；高地的；向北部的","ex":{"en":"the upper reaches of the river","cn":"河流的上游"}},{"en":"the top part of a shoe that is attached to the sole","cn":"鞋帮；靴面","ex":{"en":"shoes with leather uppers","cn":"皮鞋"},"pos":"noun"},{"en":"a drug that makes you feel excited and full of energy","cn":"兴奋剂","lab":"informal","pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ-COMPAR 形容词比较级形式","cn":"较高的；上面的","en":"You use upper to describe something that is above something else.","ex":{"en":"There is a smart restaurant on the upper floor","cn":"楼上有一家时尚的餐馆。"}},{"pos":"ADJ-COMPAR 形容词比较级形式","cn":"较上面的；较高的","en":"You use upper to describe the higher part of something.","ex":{"en":"...the upper part of the foot.","cn":"脚面部分"}},{"pos":"PHRASE 短语","cn":"上风；优势；有利地位","en":"If you have the upper hand in a situation, you have more power than the other people involved and can make decisions about what happens.","ex":{"en":"The government was beginning to gain the upper hand","cn":"政府开始占上风。"}},{"pos":"N-COUNT 可数名词","cn":"鞋帮","en":"The upper of a shoe is the top part of it, which is attached to the sole and the heel.","ex":{"en":"Wear well-fitting, lace-up shoes with soft uppers","cn":"穿合脚的、系带的软帮鞋。"}},{"pos":"N-COUNT 可数名词","cn":"兴奋剂","en":"Uppers are drugs that make you feel very happy, excited, and full of energy.","ex":{"en":"...people crazy on alcohol and cocaine and uppers and downers","cn":"酗酒、吸食可卡因、兴奋剂及镇静剂的人"}},{"pos":"","cn":"","en":"a stiff upper lip→see: ;"}]},"examples":[{"en":"There is an upper limit of £20 000 spent on any one project.","cn":"任何项目都有一个 2 万英镑的经费上限。"},{"en":"salaries at the upper end of the pay scale","cn":"工资级别最高的薪金"}]},"upsets":{"oxford":{"phon":"ʌpˈset","pos":"verb","senses":[{"en":"to make sb/yourself feel unhappy, anxious or annoyed","cn":"使烦恼；使心烦意乱；使生气"},{"en":"to make a plan, situation, etc. go wrong","cn":"打乱；搅乱"}]}},"uproar":{"media":{"uk":"media/uk/uproar__gb_1.mp3","us":"media/us/uproar__us_1.mp3"},"oxford":{"phon":"ˈʌprɔː(r)","pos":"noun","senses":[{"en":"a situation in which people shout and make a lot of noise because they are angry or upset about something","cn":"吵闹；喧嚣；叫喊","ex":{"en":"The room was in (an) uproar.","cn":"屋子里一片嘈杂。"}},{"en":"a situation in which there is a lot of public criticism and angry argument about something that somebody has said or done","cn":"骚动；怨愤","ex":{"en":"The article caused (an) uproar.","cn":"这篇文章引起了轩然大波。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"喧闹；吵闹；鼓噪；骚动","en":"If there is uproar, there is a lot of shouting and noise because people are very angry or upset about something.","ex":{"en":"The announcement caused uproar in the crowd","cn":"公告在人群中引起了骚动。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"骚乱；骚动","en":"You can also use uproar to refer to a lot of public criticism and debate about something that has made people angry.","ex":{"en":"The town is in uproar over the dispute","cn":"整个城市因为这次争端而陷入了骚动。"}}]},"examples":[{"en":"Her comments provoked (an) uproar from the audience.","cn":"她的评论激起了听众的鼓噪。"},{"en":"The article caused (an) uproar.","cn":"这篇文章引起了轩然大波。"}]},"upsetting":{"oxford":{"phon":"ʌpˈsetɪŋ","pos":"adjective","senses":[{"en":"making you feel unhappy, anxious or annoyed","cn":"令人不快（或忧虑、苦恼）的","ex":{"en":"I could see that it had been an upsetting experience for him.","cn":"我看得出那对于他是个痛苦的经历。"}}]},"media":{"uk":"media/uk/upsetting__gb_1.mp3","us":"media/us/upsetting__us_1.mp3"},"examples":[{"en":"an upsetting experience","cn":"令人苦恼的经历"},{"en":"Don’t do anything that would upset him.","cn":""}]},"upside":{"media":{"uk":"media/uk/upside__gb_1.mp3","us":"media/us/upside__us_1.mp3"},"oxford":{"phon":"ˈʌpsaɪd","pos":"noun","senses":[{"en":"the more positive aspect of a situation that is generally bad","cn":"（糟糕局面的）好的一面，光明的一面，正面"}]},"examples":[{"en":"The upside of the whole thing is that we got a free trip to Jamaica.","cn":"整个事情的好处是我们得到一次免费去牙买加旅行的机会。"}]},"uprightness":{"oxford":{"phon":"ˈʌpraɪtnəs","pos":"noun","senses":[{"en":"behaviour or attitudes that are very moral and honest","cn":"正直的行为（或态度）；诚实；公正"}]},"media":{"uk":"media/uk/uprightness__gb_1.mp3","us":"media/us/uprightness__us_1.mp3"},"examples":[{"en":"The chimpanzee stood upright and grasped the bars of its cage.","cn":""},{"en":"Katie was still awake, sitting bolt upright (= sitting with her back very straight ) staring at the television.","cn":""}]},"ups":{"oxford":{"phon":"ʌp","pos":"adverb","senses":[{"en":"towards or in a higher position","cn":"向（或在）较高位置；向上；在上面"},{"en":"to or at a higher level","cn":"向（或在）较高水平；加大；增高"}]},"media":{"uk":"media/uk/up__gb_1.mp3","us":"media/us/up__us_1.mp3"},"examples":[{"en":"I think I'll ship it UPS.","cn":""},{"en":"Will UPS take a box that big?","cn":""}]},"upon":{"media":{"uk":"media/uk/upon__gb_1.mp3","us":"media/us/upon__us_1.mp3"},"oxford":{"phon":"əˈpɒn","pos":"preposition","senses":[{"en":"used to emphasize that there is a large number or amount of something","cn":"（强调数目或数量大）","ex":{"en":"mile upon mile of dusty road","cn":"绵延数英里尘土飞扬的道路"}}]},"collins":{"senses":[{"pos":"PREP 介词","cn":"在…上","en":"If one thing is upon another, it is on it.","ex":{"en":"He set the tray upon the table","cn":"他把盘子放在桌子上。"}},{"pos":"PREP 介词","cn":"一…即…；一…就…","en":"You use upon when mentioning an event that is followed immediately by another event.","ex":{"en":"The door on the left, upon entering the church, leads to the Crypt of St Issac","cn":"一进教堂左边的那扇门通往圣以撒墓。"}},{"pos":"PREP 介词","cn":"（用于名词叠用，表示数量多）","en":"You use upon between two occurrences of the same noun in order to say that there are large numbers of the thing mentioned.","ex":{"en":"Row upon row of women surged forwards","cn":"一排排的女人涌上前去。"}},{"pos":"PREP 介词","cn":"将要发生；马上来临","en":"If an event is upon you, it is just about to happen.","ex":{"en":"The long-threatened storm was upon us","cn":"酝酿多时的暴风雨就要向我们袭来。"}}]},"examples":[{"en":"The decision was based upon two considerations.","cn":"这一决定是基于两种考虑的。"},{"en":"mile upon mile of dusty road","cn":"绵延数英里尘土飞扬的道路"}]},"up":{"media":{"uk":"media/uk/up__gb_1.mp3","us":"media/us/up__us_1.mp3"},"oxford":{"phon":"ʌp","pos":"adverb","senses":[{"en":"towards or in a higher position","cn":"向（或在）较高位置；向上；在上面","ex":{"en":"He jumped up from his chair.","cn":"他从椅子上跳起来。"}},{"en":"to or at a higher level","cn":"向（或在）较高水平；加大；增高","ex":{"en":"She turned the volume up.","cn":"她把音量调大了。"}},{"en":"to the place where somebody/something is","cn":"朝（某人或某物）的方向；向…的地方","ex":{"en":"A car drove up and he got in.","cn":"一辆汽车开过来，他就上了车。"}},{"en":"out of bed","cn":"未上床；起床","lab":"British English","ex":{"en":"I stayed up late (= did not go to bed until late) last night.","cn":"我昨晚熬夜了。"}},{"en":"to or at an important place, especially a large city","cn":"到，朝，在（重要地方，尤指大城市）","lab":"British English, formal，，","ex":{"en":"We're going up to New York for the day.","cn":"我们要上纽约一天。"}},{"en":"to a place in the north of a country; further north than somewhere else","cn":"向（北部）；向（北方）","ex":{"en":"They've moved up north.","cn":"他们已搬到北部去了。"}},{"en":"completely","cn":"完全；十足；彻底","ex":{"en":"We ate all the food up.","cn":"我们把食物吃光了。"}},{"en":"so as to be finished or closed","cn":"（以便）完结，关闭","ex":{"en":"I have some paperwork to finish up.","cn":"我有些文案工作要做完。"}},{"en":"into pieces or parts","cn":"成碎片；分开","ex":{"en":"She tore the paper up.","cn":"她把纸撕得粉碎。"}},{"en":"so as to be formed or brought together","cn":"（以便）形成，聚拢","ex":{"en":"The government agreed to set up a committee of inquiry.","cn":"政府同意成立一个调查委员会。"}},{"en":"finished; over","cn":"已结束；已过去","ex":{"en":"Time's up. Stop writing and hand in your papers.","cn":"时间到了。不要再写了，把试卷交上来。"}},{"en":"used to say that something is happening, especially something unusual or unpleasant","cn":"（尤指异常或不愉快的事情）发生，出现","lab":"informal","ex":{"en":"I could tell something was up by the looks on their faces.","cn":"从他们的脸色我就知道出事了。"}},{"en":"about to happen, be discussed, etc.","cn":"即将发生；即将进行","ex":{"en":"Next up in our top ten is a new release by Ariana Grande.","cn":"在我们的排名前十中，接下来是阿里安娜·格兰德的新歌。"}},{"en":"to or in a higher position somewhere","cn":"向，在（较高位置）","ex":{"en":"She climbed up the flight of steps.","cn":"她爬上了那段楼梯。"},"pos":"preposition"},{"en":"along or further along a road or street","cn":"沿着；顺着","ex":{"en":"We live just up the road, past the post office.","cn":"我们就住在路的前面，刚过邮局的地方。"},"pos":"preposition"},{"en":"towards the place where a river starts","cn":"向…上游；溯流而上","ex":{"en":"a cruise up the Rhine","cn":"乘船沿莱茵河溯流而上"},"pos":"preposition"},{"en":"directed or moving upwards","cn":"向上的；往上移动的","g":"[only before noun]","ex":{"en":"an up stroke","cn":"上提笔画"},"pos":"adjective"},{"en":"cheerful; happy or excited","cn":"高兴；快乐；激动","g":"[not before noun]","lab":"informal","ex":{"en":"The mood here is resolutely up.","cn":"这里的气氛十分热闹。"},"pos":"adjective"},{"en":"working","cn":"在运行","g":"[not before noun]","ex":{"en":"Our system should be up by this afternoon.","cn":"到今天下午，我们的电脑系统应该运行起来了。"},"pos":"adjective"},{"en":"to suddenly move or do something unexpected","cn":"突然移动；突然做（意想不到的事）","g":"[intransitive]","lab":"informal or humorous","ex":{"en":"He upped and left without telling anyone.","cn":"他突然起身不辞而别。"},"pos":"verb"},{"en":"to increase the price or amount of something","cn":"提高…的价格（或数量）","g":"[transitive]","ex":{"en":"The buyers upped their offer by £1 000.","cn":"买方把出价增加了 1 000 英镑。"},"pos":"verb"},{"en":"higher; upwards; towards the top of something","cn":"更高；向上；朝顶部","ex":{"en":"upland","cn":"高地"},"pos":"prefix"}]},"collins":{"senses":[{"pos":"PREP 介词","cn":"向上；朝上；往上","en":"If a person or thing goes up something such as a slope, ladder, or chimney, they move away from the ground or to a higher position.","ex":{"en":"They were climbing up a narrow mountain road","cn":"他们正沿一条狭窄的山路向上爬。"}},{"pos":"PREP 介词","cn":"近顶端；靠顶端","en":"If a person or thing is up something such as a ladder or a mountain, they are near the top of it.","ex":{"en":"He was up a ladder sawing off the tops of his apple trees","cn":"他正站在梯子顶上锯他那颗苹果树的树冠。"}},{"pos":"ADV 副词","cn":"（目光）朝上，向上","en":"You use up to indicate that you are looking or facing in a direction that is away from the ground or towards a higher level.","ex":{"en":"Paul answered, without looking up","cn":"保罗头也没抬地答了话。"}},{"pos":"ADV 副词","cn":"（站）起","en":"If someone stands up, they move so that they are standing.","ex":{"en":"He stood up and went to the window","cn":"他起身走向窗户。"}},{"pos":"PREP 介词","cn":"沿着；靠着","en":"If you go or look up something such as a road or river, you go or look along it. If you are up a road or river, you are somewhere along it.","ex":{"en":"A line of tanks came up the road from the city","cn":"一排坦克由市里沿路开来。"}},{"pos":"ADV 副词","cn":"向(或在)某地;(尤指)向(或在)北方，向(或在)地势更高处;","en":"If you are travelling to a particular place, you can say that you are going up to that place, especially if you are going towards the north or to a higher level of land. If you are already in such a place, you can say that you are up there.","ex":{"en":"I'll be up to see you tomorrow","cn":"我明天来看你。"}},{"pos":"ADV 副词","cn":"往；朝","en":"If you go up to something or someone, you move to the place where they are and stop there.","ex":{"en":"The girl ran the rest of the way across the street and up to the car","cn":"那个女孩开始跑起来，一路跑到街对面的汽车旁边。"}},{"pos":"ADV 副词","cn":"上涨；增多","en":"If an amount of something goes up, it increases. If an amount of something is up, it has increased and is at a higher level than it was.","ex":{"en":"They recently put my rent up","cn":"他们最近提高了我的租金。"}},{"pos":"ADJ 形容词","cn":"起床的","en":"If you are up, you are not in bed.","ex":{"en":"Are you sure you should be up?","cn":"你肯定你该起床了吗？"}},{"pos":"ADJ 形容词","cn":"（时间）结束的，用完的，到点的","en":"If a period of time is up, it has come to an end.","ex":{"en":"The moment the half-hour was up, Brooks rose","cn":"半个小时一到，布鲁克斯便起来了。"}},{"pos":"ADJ 形容词","cn":"（道路）正在整修的","en":"You say that a road is up when it is being repaired and cannot be used.","ex":{"en":"Half the road was up in Leadenhall Street, so their taxi was obliged to make a detour.","cn":"半条利德霍尔街都在修路，他们的出租车只好绕道走。"}},{"pos":"ADJ 形容词","cn":"（指棒球运动员）该上场击球的","en":"If a baseball player is up, it is their turn to bat."},{"pos":"ADJ 形容词","cn":"（电脑）已启动的，正常运转的","en":"If a computer or computer system is up, it is working."},{"pos":"EXCLAM 感叹语","cn":"去你的！去你妈的！","en":"People sometimes say 'Up yours!' as an insult when you have said something to annoy them or make them angry.","ex":{"en":"'Up yours,' said the reporter and stormed out into the street.","cn":"“去你的，”记者边说边怒气冲冲地冲到大街上。"}},{"pos":"PHRASE 短语","cn":"可以下床走动","en":"If someone who has been in bed for some time, for example because they have been ill, is up and about, they are now out of bed and living their normal life.","ex":{"en":"How are you Lennox? Good to see you up and about.","cn":"你怎么样，伦诺克斯？很高兴看到你能下床走动了。"}},{"pos":"PHRASE 短语","cn":"不对劲；出问题","en":"If you say that something is up, you mean that something is wrong or that something worrying is happening.","ex":{"en":"What is it then? Something's up, isn't it?","cn":"那是怎么回事呢？出问题了，是吗？"}},{"pos":"PHRASE 短语","cn":"出什么事啦？出什么问题啦？出什么毛病啦？","en":"If you say to someone 'What's up?' or if you tell them what's up, you are asking them or telling them what is wrong or what is worrying them.","ex":{"en":"'What's up?', I said to him. — 'Nothing much,' he answered","cn":"“出什么事啦？”我对他说。——“没什么事，”他答道。"}},{"pos":"PHRASE 短语","cn":"上上下下；来来回回","en":"If you move up and down somewhere, you move there repeatedly in one direction and then in the opposite direction.","ex":{"en":"He continued to jump up and down like a boy at a football match","cn":"他不停地上蹿下跳，活像个足球赛中的男孩。"}},{"pos":"PHRASE 短语","cn":"兴衰；浮沉；起落；悲欢","en":"If you have ups and downs, you experience a mixture of good things and bad things.","ex":{"en":"Every relationship has a lot of ups and downs","cn":"每一段感情都有许多起伏。"}},{"pos":"PHRASE 短语","cn":"欣欣向荣；兴旺；红火","en":"If something is on the up or on the up and up, it is becoming more successful.","ex":{"en":"They're saying that the economy is on the up","cn":"他们称经济正在企稳向好。"}},{"pos":"PHRASE 短语","cn":"安分守己；诚实可靠","en":"If someone is on the up and up, they are honest and sincere.","ex":{"en":"I'm a pretty good judge of men. If you're honest and on the up and up, I'll be able to tell it.","cn":"我看人很准的。你要是诚实正派，我能看出来的。"}},{"pos":"","cn":"","en":"up in arms→see: ;"},{"pos":"PREP-PHRASE 短语介词","cn":"胜任；有能力","en":"If you feel up to doing something, you are well enough to do it.","ex":{"en":"Those patients who were up to it could move to the adjacent pool","cn":"身体状况允许的病人可去隔壁的游泳池。"}},{"pos":"PREP-PHRASE 短语介词","cn":"搞小动作;做手脚","en":"To be up to something means to be secretly doing something that you should not be doing.","ex":{"en":"Why did you need a room unless you were up to something?","cn":"除非你要搞什么小动作，不然你为什么单要一间房？"}},{"pos":"PREP-PHRASE 短语介词","cn":"由…负责","en":"If you say that it is up to someone to do something, you mean that it is their responsibility to do it.","ex":{"en":"It was up to him to make it right, no matter how long it took","cn":"由他负责把事情摆平，不管花多长时间。"}},{"pos":"PREP-PHRASE 短语介词","cn":"直至；直到","en":"Up until or up to are used to indicate the latest time at which something can happen, or the end of the period of time that you are referring to.","ex":{"en":"Please feel free to call me any time up until half past nine at night","cn":"晚上9点半之前任何时间你都可以给我打电话。"}},{"pos":"PREP-PHRASE 短语介词","cn":"高达；多达","en":"You use up to to say how large something can be or what level it has reached.","ex":{"en":"Up to twenty thousand students paid between five and six thousand dollars","cn":"多达20,000名学生支付了5,000到6,000美元。"}},{"pos":"PHRASE 短语","cn":"马马虎虎；不怎么样","en":"If you say that something is not up to much, you mean that it is of poor quality.","ex":{"en":"My own souffles aren't up to much","cn":"我做的蛋奶酥拿不出手。"}},{"pos":"PREP-PHRASE 短语介词","cn":"在被考虑之列","en":"If someone or something is up for election, review, or discussion, they are about to be considered.","ex":{"en":"A third of the Senate and the entire House are up for re-election.","cn":"参议院三分之一的席位和众议院所有席位都面临改选。"}},{"pos":"PREP-PHRASE 短语介词","cn":"遭遇，面临（困难或问题）","en":"If you are up against something, you have a very difficult situation or problem to deal with.","ex":{"en":"The chairwoman is up against the greatest challenge to her position","cn":"女主席正面临职位上的最大挑战。"}},{"pos":"","cn":"","en":"up to your ears→see: ; up to the mark→see: ; up to par→see: ; up to scratch→see: ;"},{"pos":"VERB 动词","cn":"提高；提升；增加","en":"If you up something such as the amount of money you are offering for something, you increase it.","ex":{"en":"He upped his offer for the company","cn":"他提高了给该公司的报价。"}},{"pos":"VERB 动词","cn":"（常指突然）离开，走开","en":"If you up and leave a place, you go away from it, often suddenly or unexpectedly.","ex":{"en":"A man who for months had been dropping amorous hints about a long-term relationship upped and disappeared to America","cn":"几个月来不断暗示爱意、想发展长期恋爱关系的男人却突然远走美国。"}}]},"examples":[{"en":"It may not have been the worst week of my life but it's up there.","cn":"这可能不是我一生中最糟糕的一周，但也差不远了。"},{"en":"OK, it's not my absolute dream, but it's up there.","cn":"是的，那不是我的终极梦想，不过也差不远了。"}]},"upgrades":{"oxford":{"phon":"ˌʌpˈɡreɪd","pos":"verb","senses":[{"en":"to make a piece of machinery, computer system, etc. more powerful and efficient","cn":"使（机器、计算机系统等）升级；提高；改进"},{"en":"to give sb a more important job","cn":"提升；提拔"}]}},"uppers":{"oxford":{"phon":"ˈʌpə(r)","pos":"adjective","senses":[{"en":"located above sth else, especially sth of the same type or the other of a pair","cn":"上边的，上面的，上层的（尤指同类或一对中的一个）"},{"en":"at or near the top of sth","cn":"上部的；靠上部的"}]}},"upland":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"高地的；高原的","en":"Upland places are situated on high land.","ex":{"en":"...San Marino, the tiny upland republic","cn":"圣马力诺，面积狭小的高地共和国"}},{"pos":"N-PLURAL 复数名词","cn":"高地；高原；山地","en":"Uplands are areas of high land.","ex":{"en":"Flooding was caused by water gushing into rivers from uplands.","cn":"从山地奔流而下的水涌入河中引发了洪水。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the parts of a country that are away from the sea and are higher than other areas","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/6/brelasdeuplands.mp3","us":"media/ldoce/hwd/ame/3/laaduplands.mp3"},"examples":[{"en":"upland agriculture","cn":"山区农业"}],"oxford":{"phon":"ˈʌplənd","pos":"noun","senses":[{"en":"an area of high land that is not near the coast","cn":"（内陆）高地；山地","ex":{"en":"Conservation groups are concerned to protect wildlife in the uplands of Britain.","cn":"保护组织致力于保护英国高地的野生动物。"}},{"en":"in or connected with an area of high land that is not near the coast","cn":"（内陆）高地；山地","ex":{"en":"upland agriculture","cn":"高地农业"},"pos":"adjective"}]}},"upload":{"collins":{"senses":[{"pos":"VERB 动词","cn":"上传；上载","en":"If you upload data, you transfer it to your computer or from your computer to another computer."}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to look at information on the Internet, especially when you look quickly in order to find something that interests you","cn":""},{"en":"to copy a file from the Internet onto your own computer","cn":""},{"en":"to copy something from your computer onto the Internet","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/a/ld44upload.mp3","us":"media/ldoce/hwd/ame/a/upload.mp3"},"examples":[{"en":"It might take a while for this to upload.","cn":"上载这个可能要花些时间。"},{"en":"tips on handling file uploads","cn":"关于如何上传文件的提示"}],"oxford":{"phon":"ˌʌpˈləʊd","pos":"verb","senses":[{"en":"to send data to another computer","cn":"上传","ex":{"en":"The data was uploaded on Friday July 28 at 11:23.","cn":"该数据于 7 月 28 日星期五 11:23 上传。"}},{"en":"data that has been moved to a larger computer system from a smaller one","cn":"上载（或上传）的数据","pos":"noun"}]}},"upshot":{"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"（通常指意外的）结果，结局","en":"The upshot of a series of events or discussions is the final result of them, usually a surprising result.","ex":{"en":"The upshot is that we have lots of good but not very happy employees","cn":"结果是我们有很多优秀然而却不太快乐的员工。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"something that happens because of someone's actions or because of something else that happened before","cn":""},{"en":"when a person or situation is changed by something that happens or something that someone does","cn":""},{"en":"the consequences of an action, decision etc are the things that happen as a result of it, which are usually bad","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"The upshot of an action is the end result, whatever happens last as a consequence of the original action. The upshot of reading this sentence is that you will understand what the word upshot means."}]},"media":{"uk":"media/ldoce/hwd/bre/9/upshot0205.mp3","us":"media/ldoce/hwd/ame/f/upshot.mp3"},"examples":[{"en":"The upshot of it all was that he left college and got a job.","cn":"事情的结局是，他离开学院并投身工作了。"},{"en":"The upshot was that after much argument they all agreed to help her.","cn":"最后的结果是﹐经过长时间争论﹐他们全都同意帮助她。"}]},"upsurge":{"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"飙升；急剧增长","en":"If there is an upsurge in something, there is a sudden, large increase in it.","ex":{"en":"...the upsurge in oil prices","cn":"油价的暴涨"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a sudden increase","cn":"急剧上升﹐猛增﹐飙升"},{"en":"a sudden strong feeling 〔","cn":"情绪的〕高涨﹐激发"}]},"vocab":{"pos":"n","senses":[{"en":"An upsurge is when there's a sudden rise of something's strength or size. Hordes of people walking around your town with cameras might be due to an upsurge in tourism, for example."}]},"collocations":{"phrases":["ADJ. great, massive | sudden","PREP. ~ in an upsurge in violent crime"]},"media":{"uk":"media/ldoce/hwd/bre/7/upsurge0205.mp3","us":"media/ldoce/hwd/ame/3/upsurge.mp3"},"examples":[{"en":"a recent upsurge of interest in his movies","cn":"最近他的电影掀起的一阵热潮"},{"en":"an upsurge in violent crime","cn":"暴力犯罪的猛增"}],"oxford":{"phon":"ˈʌpsɜːdʒ","pos":"noun","senses":[{"en":"a sudden large increase in something","cn":"急剧上升；飙升；猛增","ex":{"en":"an upsurge in violent crime","cn":"暴力犯罪的猛增"}}]}},"upraised":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"举起的；抬起的；提高的","en":"If your hand or an object is upraised, you are holding it up in the air.","ex":{"en":"A soldier stood on the centre line of the road, his arm upraised.","cn":"一名士兵站在道路中心线上，一只胳膊高高举起。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"raised or lifted up – used especially about someone’s hand or arm 〔","cn":"尤指手或手臂〕举起的﹐扬起的"}]},"media":{"uk":"media/ldoce/hwd/bre/1/ld41upraised.mp3","us":"media/ldoce/hwd/ame/e/laadupraised.mp3"},"examples":[{"en":"She strode towards them, her fist upraised.","cn":"她举着拳头，大步迈向他们。"}],"oxford":{"phon":"ˌʌpˈreɪzd","pos":"adjective","senses":[{"en":"lifted upwards","cn":"举起的；扬起的","ex":{"en":"She strode towards them, her fist upraised.","cn":"她举着拳头，大步迈向他们。"}}]}},"upholder":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"拥护者;支持者;赞成者","en":"An upholder of a particular tradition or system is someone who believes strongly in it and will support it when it is threatened.","ex":{"en":"...upholders of the traditional family unit.","cn":"传统家庭形式的拥护者"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if a parliament or similar group passes a law or proposal, the members vote to accept it","cn":""},{"en":"to officially accept something that has been planned to happen","cn":""},{"en":"to officially agree to accept an agreement that someone else has already agreed to accept","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/f/uphold0205.mp3","us":"media/ldoce/hwd/ame/8/uphold.mp3"},"examples":[{"en":"an upholder of traditional values","cn":"支持传统价值观的人"},{"en":"a committee that aims to uphold educational standards","cn":""}],"oxford":{"phon":"ʌpˈhəʊldə(r)","pos":"noun","senses":[{"en":"a person who supports something that they think is right and makes sure that it continues to exist","cn":"支持，维护（正义等）","ex":{"en":"an upholder of traditional values","cn":"维护传统价值观的人"}}]}},"upholsterer":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"椅套工；座套工","en":"An upholsterer is someone whose job is to make and fit the soft covering on chairs and seats."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone whose job is to cover chairs with material","cn":"座椅套垫装饰工"}]},"media":{"uk":"media/ldoce/hwd/bre/5/ld41upholsterer.mp3","us":"media/ldoce/hwd/ame/5/ld41upholsterer.mp3"},"oxford":{"phon":"ʌpˈhəʊlstərə(r)","pos":"noun","senses":[{"en":"a person whose job is to upholster furniture","cn":"家具装饰商"}]}},"upkeep":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"维修；保养；养护","en":"The upkeep of a building or place is the work of keeping it in good condition.","ex":{"en":"The money will be used for the estate's upkeep","cn":"这笔钱将用于物业维护。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"赡养；供养；（公共事业的）维持","en":"The upkeep of a group of people or services is the process of providing them with the things that they need.","ex":{"en":"He offered to pay £100 a month towards his son's upkeep.","cn":"他愿意每月付100英镑作为儿子的抚养费。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to keep something in good condition and make sure that it does not get broken, damaged, or stolen","cn":""},{"en":"to look after something that belongs to someone else for a short time, by watching it to make sure that it does not get stolen or damaged","cn":""},{"en":"to make sure that a car, machine, place, or building is in good condition by checking it and repairing it when necessary","cn":""}]},"collocations":{"phrases":["VERB + UPKEEP contribute to, pay for Our taxes help pay for the upkeep of the city's parks. | afford","PHRASES responsible/responsibility for the upkeep of The local council is responsible for the upkeep of roads."]},"media":{"uk":"media/ldoce/hwd/bre/5/upkeep0205.mp3","us":"media/ldoce/hwd/ame/4/upkeep.mp3"},"examples":[{"en":"Tenants are responsible for the upkeep of rented property.","cn":"承租人应负责维修租用的房产。"},{"en":"He makes payments to his ex-wife for the upkeep of their children.","cn":"他向前妻支付子女的抚养费。"}],"oxford":{"phon":"ˈʌpkiːp","pos":"noun","senses":[{"en":"the cost or process of keeping something in good condition","cn":"保养（费）；维修（费）","ex":{"en":"Tenants are responsible for the upkeep of rented property.","cn":"承租人应负责维修租用的房产。"}},{"en":"the cost or process of giving a child or an animal the things that they need","cn":"抚养（费）；喂养（成本）","ex":{"en":"He makes payments to his ex-wife for the upkeep of their children.","cn":"他向前妻支付子女的抚养费。"}}]}},"upcoming":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"即将发生(或来到)的","en":"Upcoming events will happen in the near future.","ex":{"en":"...the upcoming Asian Games in Beijing","cn":"即将在北京举行的亚运会"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"if something that you are hoping for is in sight , you think it will probably happen soon","cn":""},{"en":"if something is around the corner , it might happen very soon but you cannot be completely sure","cn":""},{"en":"to be likely to happen soon, although you do not know exactly when","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/c/upcoming0205.mp3","us":"media/ldoce/hwd/ame/d/upcoming.mp3"},"examples":[{"en":"a single from the band's upcoming album","cn":"选自该乐队即将发行的专辑的一首单曲"},{"en":"the upcoming presidential election","cn":"即将举行的总统选举"}],"oxford":{"phon":"ˈʌpkʌmɪŋ","pos":"adjective","senses":[{"en":"going to happen soon","cn":"即将发生的；即将来临的","ex":{"en":"the upcoming presidential election","cn":"即将举行的总统选举"}}]}},"up-and-coming":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"有作为的；有希望的；有前途的","en":"Up-and-coming people are likely to be successful in the future.","ex":{"en":"...his readiness to share the limelight with young, up-and-coming stars","cn":"他愿与冉冉升起的年轻新星分享聚光灯"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"if a product, company, your job etc takes off , it suddenly starts being successful","cn":""},{"en":"to be becoming richer, more successful etc","cn":""},{"en":"an artist, player etc, especially a young one, who is getting more and more successful and who will probably soon be famous","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/2/up_and_coming0205.mp3","us":"media/ldoce/hwd/ame/1/up-and-coming.mp3"},"examples":[{"en":"up-and-coming young actors","cn":"前程似锦的年轻演员"},{"en":"up-and-coming young artists","cn":"有前途的年轻艺术家"}],"oxford":{"phon":"ˌʌp ən ˈkʌmɪŋ","pos":"adjective","senses":[{"en":"likely to be successful and popular in the future","cn":"有前途的；前程似锦的","ex":{"en":"up-and-coming young actors","cn":"前程似锦的年轻演员"}}]}},"upstream":{"collins":{"senses":[{"pos":"ADV 副词","cn":"逆流地；往上游；在上游","en":"Something that is moving upstream is moving towards the source of a river, from a point further down the river. Something that is upstream is towards the source of a river.","ex":{"en":"The water rose high enough for them to continue upstream.","cn":"水位涨得够高了，他们可以继续向上游航行。"}}]},"ldoce":{"phon":"hwd","pos":"adverb","senses":[{"en":"along a river, in the opposite direction from the way the water is flowing","cn":"向上游，逆流(地)"}]},"media":{"uk":"media/ldoce/hwd/bre/0/upstream0205.mp3","us":"media/ldoce/hwd/ame/5/upstream.mp3"},"examples":[{"en":"The nearest town is about ten miles upstream.","cn":"最近的城镇大约在沿河向上十英里处。"},{"en":"upstream of/from the bridge","cn":"在桥的上游"}],"oxford":{"phon":"ˌʌpˈstriːm","pos":"adverb","senses":[{"en":"along a river, in the opposite direction to the way in which the water flows","cn":"向（或在）上游；逆流","ex":{"en":"The nearest town is about ten miles upstream.","cn":"最近的城镇大约在沿河向上十英里处。"}}]}},"uplift":{"collins":{"senses":[{"pos":"VERB 动词","cn":"使振奋；提升","en":"If something uplifts people, it helps them to have a better life, for example by making them feel happy or by improving their social conditions.","ex":{"en":"We need a little something to help sometimes, to uplift us and make us feel better","cn":"有时候，我们需要一些小东西来激励自己，使自己感觉更好。"}},{"pos":"N-COUNT 可数名词","cn":"上扬；上涨；增长","en":"In economics, an uplift in something such as the price of shares is an increase in their value.","ex":{"en":"...an uplift in the stock market","cn":"股市上涨"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an increase in something","cn":"增加﹐增长"},{"en":"a feeling of happiness and hope","cn":"鼓舞﹐振奋"},{"en":"to make someone feel happier","cn":"使〔某人〕振奋﹐鼓舞"}]},"media":{"uk":"media/ldoce/hwd/bre/8/uplift_n0205.mp3","us":"media/ldoce/hwd/ame/5/l3uplift.mp3"},"examples":[{"en":"The news gave them a much needed uplift.","cn":"这消息给他们带来了及时的鼓舞。"},{"en":"an uplift bra (= that raises the breasts)","cn":"挺高式乳罩"}],"oxford":{"phon":"ˈʌplɪft","pos":"noun","senses":[{"en":"the fact of something being raised or of something increasing","cn":"提高；抬高；增长；增加","ex":{"en":"an uplift in sales","cn":"销售的增长"}},{"en":"a feeling of hope and happiness","cn":"振奋；鼓舞","ex":{"en":"The news gave them a much needed uplift.","cn":"这消息给他们带来了及时的鼓舞。"}},{"en":"the process or result of land being moved to a higher level by movements inside the earth","cn":"（地壳的）隆起，上升；抬升","lab":"geology"},{"en":"to make somebody feel happier or give somebody more hope","cn":"鼓励；激励；使振奋","pos":"verb"}]}},"uppity":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"自大的；骄横的","en":"If you say that someone is uppity, you mean that they are behaving as if they were very important and you do not think that they are important.","ex":{"en":"If you just tried to show normal dignity, you were viewed as uppity.","cn":"就算是只想表现出正常的尊严，也会被人认为是骄傲自大。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"behaving as if you are more important than you really are, or not showing someone enough respect","cn":"傲慢的﹐自大的﹐盛气凌人的"}]},"media":{"uk":"media/ldoce/hwd/bre/8/ld41uppity.mp3","us":"media/ldoce/hwd/ame/e/uppity.mp3"},"examples":[{"en":"uppity kids","cn":"目中无人的小孩"}],"oxford":{"phon":"ˈʌpəti","pos":"adjective","senses":[{"en":"behaving as if you are more important than you really are, especially when this means that you refuse to obey orders","cn":"傲慢的；自视甚高（而不服从）的"}]}},"upscale":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（产品或服务）高档的,质优价高的","en":"Upscale is used to describe products or services that are expensive, of good quality, and intended to appeal to people in a high social class.","ex":{"en":"Vodka has acquired an upscale image in the US.","cn":"伏特加在美国已树立起高档商品的形象。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"relating to people from a high social class who have a lot of money","cn":"高消费阶层的﹐高端市场的"}]},"vocab":{"pos":"adj","senses":[{"en":"Things that are upscale are made for rich people — they are high class, well made, or just plain pricey."}]},"media":{"uk":"media/ldoce/hwd/bre/c/ld41upscale.mp3","us":"media/ldoce/hwd/ame/3/upscale.mp3"},"examples":[{"en":"an affluent upscale audience","cn":"富裕的高消费观众"}],"oxford":{"phon":"ˌʌpˈskeɪl","pos":"adverb","senses":[{"en":"in a way that involves buying or selling goods and services that are expensive and of high quality","cn":"向高档，向高级消费市场"},{"en":"designed for or used by people who belong to a high social class or have a lot of money","cn":"高档的；高级的","pos":"adjective"},{"en":"to make something better, bigger or more powerful","cn":"改进；扩大；升级","ex":{"en":"The pilot project will begin in three areas and then be upscaled to the entire state.","cn":"该试点项目将先在三个地区推行，然后扩展至整个州。"},"pos":"verb"},{"en":"to change a product so that it will be used or bought by people who have more money or belong to a higher social class","cn":"使（产品）更高档","ex":{"en":"The complimentary snacks at the bar have been upscaled.","cn":"酒吧的免费小吃已经升级。"},"pos":"verb"}]}},"uppercut":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（拳击中的）上钩拳","en":"An uppercut is a type of punch used in boxing. It is a hard upward blow to the chin.","ex":{"en":"He was knocked down by an uppercut from Eubank.","cn":"他被尤班克一记上钩拳击倒在地。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a way of hitting someone in which you swing your hand up into their chin","cn":"上钩拳"}]},"media":{"uk":"media/ldoce/hwd/bre/a/ld41uppercut.mp3","us":"media/ldoce/hwd/ame/0/uppercut.mp3"},"oxford":{"phon":"ˈʌpəkʌt","pos":"noun","senses":[{"en":"a way of hitting somebody on the chin (= part of the face below the mouth), in which you bend your arm and move your hand upwards","cn":"上勾拳"}]}},"uppermost":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"最高的；最上面的","en":"The uppermost part of something is the part that is higher than the rest of it. The uppermost thing is the highest one of a group of things.","ex":{"en":"John was on the uppermost floor of the three-storey gatehouse","cn":"约翰在三层门房的最高层。"}},{"pos":"ADJ 形容词","cn":"最重要的；最主要的","en":"If something is uppermost in a particular situation, it is the most important thing in that situation.","ex":{"en":"The economy appears to be uppermost in people's minds","cn":"大家心里最关心的似乎是经济。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"at the top above the lower part of something","cn":""},{"en":"the topmost or uppermost part of something is the highest of all its parts, right at the top","cn":""},{"en":"if something is uppermost in your mind, you think about it a lot because it is very important to you","cn":"是心目中最主要的"}]},"media":{"uk":"media/ldoce/hwd/bre/f/uppermost0205.mp3","us":"media/ldoce/hwd/ame/7/uppermost.mp3"},"examples":[{"en":"Place the material on a flat surface, shiny side uppermost.","cn":"把材料放在平面上，有光的一面朝上。"},{"en":"These thoughts were uppermost in my mind.","cn":"我心里想得最多的就是这些事。"}],"oxford":{"phon":"ˈʌpəməʊst","pos":"adjective","senses":[{"en":"higher or nearer the top than other things","cn":"最高的；最上端的；最上面的","g":"[usually before noun]","lab":"formal","ex":{"en":"the uppermost branches of the tree","cn":"树顶端的枝丫"}},{"en":"more important than other things in a particular situation","cn":"最重要；最关键","g":"[not usually before noun]","ex":{"en":"These thoughts were uppermost in my mind.","cn":"我心里想的最多的就是这些事。"}},{"en":"in the highest position; facing upwards","cn":"处于最高位置；面向上地","ex":{"en":"Place the material on a flat surface, shiny side uppermost.","cn":"把材料放在平面上，有光的一面朝上。"},"pos":"adverb"}]}},"upholstery":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"座套；椅套","en":"Upholstery is the soft covering on chairs and seats that makes them more comfortable to sit on.","ex":{"en":"...white leather upholstery","cn":"白色皮座套"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"material used to cover chairs 〔","cn":"椅子的〕被覆材料﹐垫衬料"},{"en":"the process of covering chairs with material 〔","cn":"座椅的〕加套装饰"}]},"vocab":{"pos":"n","senses":[{"en":"Upholstery refers to the covering on furniture. Without upholstery , your couch wouldn't be very comfortable."}]},"media":{"uk":"media/ldoce/hwd/bre/6/upholstery0205.mp3","us":"media/ldoce/hwd/ame/3/upholstery.mp3"},"oxford":{"phon":"ʌpˈhəʊlstəri","pos":"noun","senses":[{"en":"soft material that covers furniture such as armchairs and sofas","cn":"家具装饰品（或衬垫等）"},{"en":"the process or trade of upholstering","cn":"家具装饰；家具装饰业"}]}},"upstart":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（初到某地或初出茅庐却）自命不凡的家伙","en":"You can refer to someone as an upstart when they behave as if they are important, but you think that they are too new in a place or job to be treated as important.","ex":{"en":"Many prefer a familiar authority figure to a young upstart.","cn":"很多人都更愿意跟自己熟悉的权威人物打交道，而不是一个年纪轻轻却自命不凡的家伙。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who behaves as if they were more important than they really are and who shows a lack of respect towards people who are more experienced or older","cn":"目中无人的新人[年轻人]﹔自命不凡的家伙"}]},"vocab":{"pos":"1 n adj 2 n","senses":[{"en":"An upstart is someone who's cocky and arrogant, and who doesn't show much respect for other people."}]},"media":{"uk":"media/ldoce/hwd/bre/2/upstart0205.mp3","us":"media/ldoce/hwd/ame/f/upstart.mp3"},"examples":[{"en":"a cheeky young upstart","cn":"傲慢无礼的后生小子"}],"oxford":{"phon":"ˈʌpstɑːt","pos":"noun","senses":[{"en":"a person who has just started in a new position or job but who behaves as if they are more important than other people, in a way that is annoying","cn":"自命不凡的新上任者；狂妄自大的新手"}]}},"upmarket":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（产品或服务）高端的，高档的","en":"Upmarket products or services are expensive, of good quality, and intended to appeal to people in a high social class.","ex":{"en":"Anne chose an upmarket agency aimed at professional people.","cn":"安妮选择了一家以专业人士为服务对象的高端代理商。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"an expensive hotel, restaurant, area etc is very fashionable and it is expensive to stay, eat, or live there","cn":""},{"en":"an exclusive area, school, shop, club etc is very expensive, and only a few very rich people have enough money to live there or use it","cn":""},{"en":"a luxurious building or room is large, very comfortable, and has expensive decorations and furniture","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/b/brelasdeupmarket.mp3","us":"media/ldoce/hwd/ame/a/laadupmarket.mp3"},"examples":[{"en":"The company has been forced to move more upmarket.","cn":"这家公司被迫进一步转向高端市场。"},{"en":"an upmarket restaurant","cn":"高级餐厅"}],"oxford":{"phon":"ˌʌpˈmɑːkɪt","pos":"adverb","senses":[{"en":"in a way that involves buying or selling goods and services that are expensive and of high quality","cn":"向高档，向高级消费市场","ex":{"en":"The company has been forced to move more upmarket.","cn":"公司被迫进一步转向高端市场。"}},{"en":"designed for or used by people who belong to a high social class or have a lot of money","cn":"高档的；高级的","ex":{"en":"an upmarket restaurant","cn":"高级餐厅"},"pos":"adjective"}]}},"uplifted":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（脸或手臂）扬起的，抬起的","en":"If people's faces or arms are uplifted, they are pointing them upwards or are holding them up.","ex":{"en":"The men support the ballerinas, who pose with their uplifted arms.","cn":"男演员托举着女芭蕾舞演员，她们在上面抬臂摆出造型。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"昂扬的；振奋的；鼓舞的；兴奋的","en":"If something makes you feel uplifted, it makes you feel very cheerful and happy.","ex":{"en":"...people whose presence left you feeling uplifted, happy and full of energy.","cn":"那些一出现就让你感到兴奋、开心和活力十足的人"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"feeling happier and more hopeful","cn":"振奋的，受鼓舞的"},{"en":"raised upwards","cn":"被提[抬，举]起的"}]},"media":{"uk":"media/ldoce/hwd/bre/3/uplifted0205.mp3","us":"media/ldoce/hwd/ame/9/laaduplifted.mp3"},"examples":[{"en":"a sea of uplifted faces","cn":"一张张扬起的脸"},{"en":"He felt uplifted by her presence.","cn":"她的出现让他觉得精神振奋。"}],"oxford":{"phon":"ˌʌpˈlɪftɪd","pos":"adjective","senses":[{"en":"feeling happy and full of hope","cn":"兴冲冲；意气昂扬","g":"[not before noun]","ex":{"en":"Everyone left the meeting feeling uplifted.","cn":"会议结束时，每个人都心情振奋。"}},{"en":"lifted upwards","cn":"抬起的；昂起的；举起的","lab":"literary","ex":{"en":"a sea of uplifted faces","cn":"一张张扬起的脸"}}]}},"upheaval":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"激变；剧变；动乱","en":"An upheaval is a big change which causes a lot of trouble, confusion, and worry.","ex":{"en":"Wherever there is political upheaval, invariably there are refugees","cn":"哪里有政治动乱，哪里就一定有难民。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a change in something, especially one that has happened gradually or naturally","cn":""},{"en":"a complete change from a bad economic situation to a good one, or a change from failing to succeeding","cn":""},{"en":"a big change in your life or in the way things are organized, especially when this causes problems and anxiety","cn":""}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"Upheaval means a violent or sudden change. You might talk about an upheaval in government following an election where many incumbents are replaced."}]},"collocations":{"phrases":["ADJ. big, enormous, great, major, massive, violent | domestic, economic, emotional, political, social The loss of his high-paying job caused","VERB + UPHEAVAL cause, provoke | go through, undergo The company underwent a massive upheaval after the takeover.","PREP. during/in the ~ He rose to power during the political upheavals of the 1990s.","PHRASES a period of upheaval"]},"media":{"uk":"media/ldoce/hwd/bre/8/upheaval0205.mp3","us":"media/ldoce/hwd/ame/1/upheaval.mp3"},"examples":[{"en":"I can't face the upheaval of moving house again.","cn":"我无法忍受再次搬家的折腾。"},{"en":"the latest upheavals in the education system","cn":"最近教育制度上的种种变更"}],"oxford":{"phon":"ʌpˈhiːvl","pos":"noun","senses":[{"en":"a big change that causes a lot of worry and problems","cn":"剧变；激变；动乱；动荡","ex":{"en":"Teachers are still getting used to the latest upheavals in the education system.","cn":"教师们仍在适应教育系统最新的剧变。"}}]}},"upbeat":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"达观的；乐观的；充满希望的","en":"If people or their opinions are upbeat, they are cheerful and hopeful about a situation.","ex":{"en":"The Defense Secretary gave an upbeat assessment of the war so far","cn":"国防部长对目前的战事给予了乐观的评价。"}},{"pos":"N-COUNT 可数名词","cn":"弱拍；上拍","en":"In music, the upbeat is the beat before the first beat of the bar."}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"believing that good things will happen","cn":""},{"en":"believing that what you hope for will happen","cn":""},{"en":"thinking about what is good in a situation, rather than what is bad","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/f/upbeat0205.mp3","us":"media/ldoce/hwd/ame/6/upbeat.mp3"},"examples":[{"en":"The tone of the speech was upbeat.","cn":"这次讲话的语气颇为乐观。"},{"en":"The meeting ended on an upbeat note.","cn":"会议在乐观的气氛中结束。"}],"oxford":{"phon":"ˈʌpbiːt","pos":"adjective","senses":[{"en":"positive and enthusiastic; making you feel that the future will be good","cn":"乐观的；快乐的；积极向上的","ex":{"en":"The tone of the speech was upbeat.","cn":"这次讲话的语气颇为乐观。"}}]}},"upend":{"collins":{"senses":[{"pos":"VERB 动词","cn":"使倒立；倒放；颠倒","en":"If you upend something, you turn it upside down.","ex":{"en":"He upended the beer, and swallowed.","cn":"他举起啤酒，一饮而尽。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to turn something over so that it is upside down","cn":"倒放﹐使颠倒"}]},"media":{"uk":"media/ldoce/hwd/bre/b/ld41upend.mp3","us":"media/ldoce/hwd/ame/7/upend.mp3"},"examples":[{"en":"The bicycle lay upended in a ditch.","cn":"自行车翻倒在一条小水沟里。"}],"oxford":{"phon":"ʌpˈend","pos":"verb","senses":[{"en":"to turn somebody/something the wrong way up or onto one end","cn":"翻倒；倒放；使颠倒","lab":"figurative","ex":{"en":"The bicycle lay upended in a ditch.","cn":"自行车翻倒在一条小水沟里。"}}]}},"up-to-date":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"something that is modern uses the most recent designs or methods","cn":""},{"en":"the newest that is available","cn":""},{"en":"using the most modern technology, ideas, information etc","cn":""}]},"collocations":{"phrases":["VERBS be | bring sth We'll have to bring our equipment up-to-date. | keep sth","ADV. really, very | bang, completely Today's holiday parks are bang up-to-date. 2 having the most recent information about sth","VERBS be, seem | keep It is difficult to keep up-to-date with all the developments. | bring sb | keep sb","ADV. completely, fully","PREP. on Bring me up-to-date on their progress. | with We can keep you fully up-to-date with your financial position."]},"media":{"uk":"media/ldoce/hwd/bre/1/up_to_date0205.mp3","us":"media/ldoce/hwd/ame/9/up-to-date.mp3"},"examples":[{"en":"They have access to up-to-date information through a computer database.","cn":"他们可以通过计算机数据库获得最新信息。"},{"en":"Our magazine will keep you up to date with fashion.","cn":"我们的杂志可以让你即时掌握最新的时尚资讯。"}],"oxford":{"phon":"ˌʌp tə ˈdeɪt","pos":"adjective","senses":[{"en":"modern; fashionable","cn":"现代化的；时髦的；流行的","ex":{"en":"This technology is bang up to date (= completely modern).","cn":"这项技术是最新的。"}},{"en":"having or including the most recent information","cn":"最新的；时新的；即时的","ex":{"en":"We are keeping up to date with the latest developments.","cn":"我们时刻留意最新的发展情况。"}}]}},"up-to-the-minute":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"最近的；最新的","en":"Up-to-the-minute information is the latest information that you can get about something.","ex":{"en":"...24 hours a day up-to-the-minute instant news","cn":"一天24小时最新消息即时播报"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"the latest news, information etc is the most recent news, information etc","cn":""},{"en":"up-to-date information is the most recent and correct information","cn":""},{"en":"up-to-the-minute news or information is the most recent news or information about something that is likely to change very quickly all the time","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/5/brelasdeup-to-the-minute.mp3","us":"media/ldoce/hwd/ame/b/up-to-the-minute.mp3"},"examples":[{"en":"up-to-the-minute designs","cn":"最时髦的设计"},{"en":"up-to-the-minute news","cn":"最新消息"}],"oxford":{"phon":"ˌʌp tə ðə ˈmɪnɪt","pos":"adjective","senses":[{"en":"having or including the most recent information","cn":"最新的；时新的；即时的","ex":{"en":"up-to-the-minute news","cn":"最新消息"}},{"en":"modern; fashionable","cn":"现代化的；时髦的；流行的","ex":{"en":"up-to-the-minute designs","cn":"最时髦的设计"}}]}},"upchuck":{"collins":{"senses":[{"pos":"VERB 动词","cn":"呕出；吐出","en":"If you upchuck, food and drink comes back up from your stomach and out through your mouth."}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to bring food or drink up from your stomach and out through your mouth because you are ill or drunk","cn":"呕吐"}]},"media":{"uk":"media/ldoce/hwd/bre/1/upchuck0205.mp3","us":"media/ldoce/hwd/ame/2/upchuck.mp3"},"oxford":{"phon":"ˈʌptʃʌk","pos":"verb","senses":[{"en":"to vomit","cn":"呕吐"}]}},"upcountry":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"内陆的；北方边远地区的","en":"Upcountry places are towards the middle or north of a large country, usually in the countryside.","ex":{"en":"...a collection of upcountry hamlets.","cn":"内地村落"}}]}},"uprising":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"起义;暴动","en":"When there is an uprising, a group of people start fighting against the people who are in power in their country, because they want to bring about a political change.","ex":{"en":"...a popular uprising against the authoritarian government","cn":"反对独裁政府的群众暴动"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an attempt by a large group of people at revolution","cn":""},{"en":"an occasion when a group of people, especially soldiers, suddenly take control of a country","cn":""},{"en":"an organized attempt to change the government or other authority, often by using violence","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"An organized rebellion, especially against an authority or government — is an uprising . If your entire math class joined together in rebellion against your teacher's unfair grading practices, you could call it an uprising ."}]},"collocations":{"phrases":["ADJ. successful | failed the failed uprising of 1830 | armed | revolutionary | mass, national, popular | military | peasant | spontaneous","VERB + UPRISING provoke, spark (off) | stage | crush, put down, quell, suppress","PREP. during/in the ~ He was killed in the Warsaw uprising. | ~ against the 1951 uprising against colonial rule"]},"media":{"uk":"media/ldoce/hwd/bre/4/uprising0205.mp3","us":"media/ldoce/hwd/ame/b/uprising.mp3"},"examples":[{"en":"an armed uprising against the government","cn":"反政府的武装起义"},{"en":"a popular uprising (= by the ordinary people of the country)","cn":"平民暴动"}],"oxford":{"phon":"ˈʌpraɪzɪŋ","pos":"noun","senses":[{"en":"a situation in which a group of people join together in order to fight against the people who are in power","cn":"起义；暴动；造反","ex":{"en":"He led an armed uprising against the government.","cn":"他领导了一场反对政府的武装起义。"}}]}},"uplifting":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"振奋人心的；鼓舞人心的；令人兴奋不已的","en":"You describe something as uplifting when it makes you feel very cheerful and happy.","ex":{"en":"...a charming and uplifting love story","cn":"引人入胜的、令人振奋的爱情故事"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"making you feel happier and more hopeful","cn":"令人振奋的，使受鼓舞的"}]},"vocab":{"pos":"1 n 2 adj","senses":[{"en":"When you stand on a beach and admire the uplifting of a kite into the blue sky, you're watching it move up. Watching that kite rise might be an uplifting , or moving, experience."}]},"collocations":{"phrases":["VERBS be, feel | find sth","ADV. really, very | suitably a suitably uplifting ending for the film | morally, spiritually"]},"media":{"uk":"media/ldoce/hwd/bre/c/brelasdeuplifting.mp3","us":"media/ldoce/hwd/ame/3/laaduplifting.mp3"},"examples":[{"en":"an uplifting experience/speech","cn":"令人振奋的经历/演说"},{"en":"an uplifting experience","cn":"令人振奋的经历"}],"oxford":{"phon":"ˌʌpˈlɪftɪŋ","pos":"adjective","senses":[{"en":"making you feel happier or giving you more hope","cn":"令人振奋的；鼓舞人心的；催人奋进的","ex":{"en":"an uplifting experience/speech","cn":"令人振奋的经历／演说"}}]}},"uproarious":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"喧嚣的；热闹的；充满喧闹哄笑声的","en":"When events or people are uproarious, they make people laugh in a very noisy way.","ex":{"en":"He had spent several uproarious evenings at the Embassy Club","cn":"他在使馆俱乐部度过了几个狂欢夜。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"very noisy, because a lot of people are laughing or shouting","cn":"喧闹的﹐人声鼎沸的"}]},"vocab":{"pos":"adj","senses":[{"en":"Uproarious situations are very loud, a little out of control, and often hilarious. You might encounter an uproarious crowd at a soccer match, or even in your school cafeteria."}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41uproarious.mp3","us":"media/ldoce/hwd/ame/8/uproarious.mp3"},"examples":[{"en":"The audience laughed uproariously.","cn":"观众哄然大笑。"},{"en":"an uproarious story","cn":"令人捧腹的故事"}],"oxford":{"phon":"ʌpˈrɔːriəs","pos":"adjective","senses":[{"en":"in which there is a lot of noise and people laugh or shout a lot","cn":"喧闹的；热烈的；吵吵嚷嚷的","ex":{"en":"an uproarious party","cn":"热闹的聚会"}},{"en":"extremely funny","cn":"滑稽的；极可笑的；令人捧腹的","ex":{"en":"an uproarious story","cn":"令人捧腹的故事"}}]}},"upriver":{"collins":{"senses":[{"pos":"ADV 副词","cn":"往上游；向上游；在上游","en":"Something that is moving up-river is moving towards the source of a river, from a point down the river. Something that is up-river is towards the source of a river.","ex":{"en":"Heavy goods could be brought up-river in barges","cn":"较重的货物可用驳船运到上游。"}}]},"ldoce":{"phon":"hwd","pos":"adverb","senses":[{"en":"away from the sea towards the place where a river begins","cn":"向上游﹐往上游"}]},"media":{"uk":"media/ldoce/hwd/bre/6/upriver0205.mp3","us":"media/ldoce/hwd/ame/0/laadupriver.mp3"},"oxford":{"phon":"ˌʌpˈrɪvə(r)","pos":"adverb","senses":[{"en":"along a river, in the opposite direction to the way in which the water flows","cn":"向（或在）上游；逆流"}]}},"upturn":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"好转；上升；改善","en":"If there is an upturn in the economy or in a company or industry, it improves or becomes more successful.","ex":{"en":"They do not expect an upturn in the economy until the end of the year","cn":"他们预测要到年底经济才能有所好转。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an increase in amount, quantity, population etc","cn":""},{"en":"an increase in numbers, level, population, or temperature","cn":""},{"en":"a gradual increase in something harmful or bad","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Use the noun upturn to describe an improvement, especially in finances or business."}]},"collocations":{"phrases":["ADJ. dramatic, sharp | slight | economic","VERB + UPTURN be on, take Sales are on the upturn. Their fortunes have taken an upturn in recent months.","UPTURN + VERB come We expect an increase in demand when the economic upturn eventually comes.","PREP. ~ in a sharp upturn in oil prices"]},"media":{"uk":"media/ldoce/hwd/bre/6/upturn0205.mp3","us":"media/ldoce/hwd/ame/9/upturn.mp3"},"examples":[{"en":"The restaurant trade is on the upturn.","cn":"餐厅业正在复苏。"},{"en":"an upturn in the economy","cn":"经济的好转"}],"oxford":{"phon":"ˈʌptɜːn","pos":"noun","senses":[{"en":"a situation in which something improves or increases over a period of time","cn":"改善；改进；回升；进步","ex":{"en":"an upturn in the economy","cn":"经济的好转"}}]}},"uproot":{"collins":{"senses":[{"pos":"VERB 动词","cn":"使离开久住之处；使迁移他处居住","en":"If you uproot yourself or if you are uprooted, you leave, or are made to leave, a place where you have lived for a long time.","ex":{"en":"...the trauma of uprooting themselves from their homes","cn":"背井离乡给他们造成的心灵创伤"}},{"pos":"VERB 动词","cn":"把…连根拔起；根除","en":"If someone uproots a tree or plant, or if the wind uproots it, it is pulled out of the ground.","ex":{"en":"They had been forced to uproot their vines and plant wheat.","cn":"他们已被迫将葡萄藤连根拔除，改种小麦。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to pull a plant and its roots out of the ground","cn":"把〔植物〕连根拔起"},{"en":"to make someone leave their home for a new place, especially when this is difficult or upsetting （","cn":"使）〔某人〕背井离乡"}]},"vocab":{"pos":"v","senses":[{"en":"When you uproot people, you move them from one place to a completely new one. Your parents may need to uproot you if your mom gets a new job all the way across the country."}]},"media":{"uk":"media/ldoce/hwd/bre/c/uproot0205.mp3","us":"media/ldoce/hwd/ame/f/uproot.mp3"},"examples":[{"en":"If I accept the job, it will mean uprooting my family and moving to Italy.","cn":"如果我接受了这份工作，那将意味着我得举家搬迁到意大利去。"},{"en":"We decided to uproot and head for Scotland.","cn":"我们决定迁往苏格兰。"}],"oxford":{"phon":"ˌʌpˈruːt","pos":"verb","senses":[{"en":"to pull a tree, plant, etc. out of the ground","cn":"将…连根拔起","g":"[transitive]","ex":{"en":"The storms uprooted a number of large trees.","cn":"暴风雨将许多大树连根拔起。"}},{"en":"to leave a place where you have lived for a long time; to make somebody do this","cn":"（使）离开家园（或熟悉的地方等）","g":"[intransitive, transitive]","ex":{"en":"We decided to uproot and head for Scotland.","cn":"我们决定迁往苏格兰。"}}]}},"up-country":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"from a place without many people or towns, especially in the middle of a country","cn":"来自内地的〔尤指地处国家中部﹑人口或城镇不多的地区〕"}]},"media":{"uk":"media/ldoce/hwd/bre/a/ld41up-country.mp3","us":"media/ldoce/hwd/ame/a/ld41up-country.mp3"},"oxford":{"phon":"ˌʌp ˈkʌntri","pos":"adjective","senses":[{"en":"relating to an area of a country that is not near large towns","cn":"内地的；偏远的；偏僻的"},{"en":"in or towards an area of a country that is not near large towns","cn":"内地的；偏远的；偏僻的","pos":"adverb"}]}},"upstate":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"州的最边远地区的；州的最北部地区的","en":"Upstate means belonging or relating to the parts of a state that are furthest to the north or furthest from the main city.","ex":{"en":"...an idyllic village in upstate New York.","cn":"纽约州最北部的一个恬静村庄"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"in the northern part of a particular state 〔","cn":"州的〕北部地区的"}]},"media":{"uk":"media/ldoce/hwd/bre/b/ld41upstate.mp3","us":"media/ldoce/hwd/ame/d/upstate.mp3"},"examples":[{"en":"They retired and went to live upstate.","cn":"他们退休后移居到州的乡野地区去了。"},{"en":"upstate New York","cn":"纽约的北部"}],"oxford":{"phon":"ˌʌpˈsteɪt","pos":"adverb","senses":[{"en":"in or to a part of a state that is far from its main cities, especially a northern part","cn":"在（或向）州的乡野地区（尤指北部）","ex":{"en":"They retired and went to live upstate.","cn":"他们退休后移居到州的乡野地区去了。"}},{"en":"in a part of a state that is far from its main cities, especially a northern part","cn":"在（或向）州的乡野地区（尤指北部）","ex":{"en":"upstate New York","cn":"纽约州北部城郊区"},"pos":"adjective"}]}},"uptown":{"collins":{"senses":[{"pos":"ADV 副词","cn":"往(或在)城外;往(或在)城镇的非商业区","en":"If you go uptown, or go to a place uptown, you go away from the centre of a town or city towards the edge. Uptown sometimes refers to a part of the city other than the main business district.","ex":{"en":"He rode uptown and made his way to Bob's apartment","cn":"他乘车前往城外鲍勃的公寓。"}}]},"ldoce":{"phon":"hwd","pos":"adverb","senses":[{"en":"in or towards an area of a city that is away from the centre, especially one where the streets have larger numbers in their names and where people have more money","cn":"在[向]城郊﹔在[向]富人区"}]},"media":{"uk":"media/ldoce/hwd/bre/a/ld41uptown.mp3","us":"media/ldoce/hwd/ame/a/uptown.mp3"},"examples":[{"en":"We walked uptown a couple of blocks until we found a cab.","cn":"我们向市郊走了好几条街才找到一辆出租车。"},{"en":"They live in an apartment uptown.","cn":"他们住在市郊的一套公寓。"}],"oxford":{"phon":"ˌʌpˈtaʊn","pos":"adverb","senses":[{"en":"in or to the parts of a town or city that are away from the centre, where people live","cn":"离开市中心；在（或向）市郊","ex":{"en":"They live in an apartment uptown.","cn":"他们住在市郊的一套公寓。"}},{"en":"in, to or typical of the parts of a town or city that are away from the centre, where people live","cn":"在（或向）市郊住宅区的；市郊住宅区的","g":"[only before noun]","ex":{"en":"an uptown train","cn":"开往市郊住宅区的火车"},"pos":"adjective"},{"en":"typical of an area of a town or city where people have a lot of money","cn":"富人区的","ex":{"en":"uptown prices","cn":"富人区的价格"},"pos":"adjective"}]}},"uptight":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"紧张不安的；忧虑的;易怒的","en":"Someone who is uptight is tense, nervous, or annoyed about something and so is difficult to be with.","ex":{"en":"Penny never got uptight about exams","cn":"彭妮从来不会因为考试而紧张。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"angry and unfriendly, and often complaining about things","cn":""},{"en":"someone who is disagreeable is bad-tempered and very unfriendly and behaves in an unpleasant way towards people","cn":""},{"en":"often becoming annoyed or unhappy, especially when there seems to be no good reason to","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"To be uptight is to be tense. When you're uptight , you're stressed out and anxious."}]},"collocations":{"phrases":["VERBS be, feel, look, seem, sound | get Try to laugh at it instead of getting uptight. | make sb","ADV. really, very | all (informal) He gets all uptight if anyone criticizes him! | a bit, quite","PREP. about He's feeling a bit uptight about his exam tomorrow."]},"media":{"uk":"media/ldoce/hwd/bre/a/uptight0205.mp3","us":"media/ldoce/hwd/ame/9/uptight.mp3"},"examples":[{"en":"Relax! You're getting too uptight about it.","cn":"轻松点儿！你对这事太紧张了。"},{"en":"an uptight teenager","cn":"腼腆的少年"}],"oxford":{"phon":"ˌʌpˈtaɪt","pos":"adjective","senses":[{"en":"anxious and/or angry about something","cn":"紧张不安的；愤怒的","ex":{"en":"Relax! You're getting too uptight about it.","cn":"放松点儿！你对这事太紧张了。"}},{"en":"nervous about showing your feelings","cn":"局促的；拘谨的；紧张的","lab":"especially North American English","ex":{"en":"an uptight teenager","cn":"腼腆的少年"}}]}},"upstanding":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"品行端正的；正直的","en":"Upstanding people behave in a morally acceptable way.","ex":{"en":"...a fine, upstanding and decent Irish citizen","cn":"一位杰出而又品行端正、作风正派的爱尔兰公民"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"honest and responsible","cn":"诚实的；有担当的"},{"en":"standing upright or pointing upwards","cn":"直立的﹔向上的"},{"en":"used in a formal situation such as a law court to tell people to stand up as a sign of respect for an important person","cn":"起立〔用于法庭等正式场合﹐要求人们站起来以示对某重要人物的尊重〕"}]},"vocab":{"pos":"adj","senses":[{"en":"The adjective upstanding is good for describing someone who is a good and honorable person, like your trusted best friend."}]},"media":{"uk":"media/ldoce/hwd/bre/0/ld41upstanding.mp3","us":"media/ldoce/hwd/ame/0/upstanding.mp3"},"examples":[{"en":"Ladies and gentlemen, please be upstanding and join me in a toast to the bride and groom.","cn":"各位来宾，请大家起立，我们一起为新娘新郎干一杯。"},{"en":"an upstanding member of the community","cn":"群体中正直的一分子"}],"oxford":{"phon":"ˌʌpˈstændɪŋ","pos":"adjective","senses":[{"en":"behaving in a moral and honest way","cn":"正直的；正派的；诚实的","ex":{"en":"an upstanding member of the community","cn":"群体中正直的一分子"}}]}},"uphold":{"collins":{"senses":[{"pos":"VERB 动词","cn":"拥护；支持；维护","en":"If you uphold something such as a law, a principle, or a decision, you support and maintain it.","ex":{"en":"Our policy has been to uphold the law","cn":"拥护法律是我们一贯的方针。"}},{"pos":"VERB 动词","cn":"维持，坚持（原判）","en":"If a court of law upholds a legal decision that has already been made, it decides that it was the correct decision.","ex":{"en":"The crown court, however, upheld the magistrate's decision.","cn":"然而，最高法院维持了地方法院的判决。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if a parliament or similar group passes a law or proposal, the members vote to accept it","cn":""},{"en":"to officially accept something that has been planned to happen","cn":""},{"en":"to officially agree to accept an agreement that someone else has already agreed to accept","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"When you uphold something, you stick up for or support it. Police officers are paid to uphold the law, and crazy Elvis fans uphold their belief that he's still alive out there somewhere."}]},"collocations":{"phrases":["ADV. firmly, resolutely, vigorously | unanimously Three judges unanimously upheld the sentence.","VERB + UPHOLD have a duty to | be determined to We are determined to uphold the law. | seek to | promise to | vote to The IWC voted to uphol"]},"media":{"uk":"media/ldoce/hwd/bre/f/uphold0205.mp3","us":"media/ldoce/hwd/ame/8/uphold.mp3"},"examples":[{"en":"to uphold a conviction/an appeal/a complaint","cn":"维持原判；受理上诉/申诉"},{"en":"We have a duty to uphold the law.","cn":"维护法律是我们的责任。"}],"oxford":{"phon":"ʌpˈhəʊld","pos":"verb","senses":[{"en":"to support something that you think is right and make sure that it continues to exist","cn":"支持，维护（正义等）","ex":{"en":"We have a duty to uphold the law.","cn":"维护法律是我们的责任。"}},{"en":"to agree that a previous decision was correct or that a request is reasonable","cn":"维持（原判）；受理（申诉）","ex":{"en":"to uphold a conviction/an appeal/a complaint","cn":"维持原判；受理上诉／申诉"}}]}},"upwind":{"collins":{"senses":[{"pos":"ADV 副词","cn":"逆风地；顶风地；在上风","en":"If something moves upwind, it moves in the opposite direction to the wind. If something is upwind, the wind is blowing away from it.","ex":{"en":"...riding a bike upwind","cn":"逆风骑车"}}]},"ldoce":{"phon":"hwd","pos":"adverb","senses":[{"en":"in the opposite direction to the way the wind is blowing","cn":"逆风地﹐顶风地"}]},"media":{"uk":"media/ldoce/hwd/bre/8/ld41upwind2.mp3","us":"media/ldoce/hwd/ame/8/ld41upwind2.mp3"},"examples":[{"en":"The house was upwind of the factory and its smells (= the wind did not blow the smells towards the house).","cn":"这房子坐落在工厂的上风处，闻不到工厂的气味。"},{"en":"to sail upwind","cn":"逆风行船"}],"oxford":{"phon":"ˌʌpˈwɪnd","pos":"adverb, adjective","senses":[{"en":"in the opposite direction to the way in which the wind is blowing","cn":"逆风（的）；顶风（的）","ex":{"en":"to sail upwind","cn":"逆风行船"}}]}},"upturned":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"朝上的；朝上翘的；向上翻的","en":"Something that is upturned points upwards.","ex":{"en":"...the rain splashing down on her upturned face.","cn":"溅落到她仰起的脸上的雨水"}},{"pos":"ADJ 形容词","cn":"翻转的；倒置的","en":"Something that is upturned is upside down.","ex":{"en":"...upturned buckets","cn":"倒扣的水桶"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"pointing or turning upwards","cn":"向上翘的﹔朝上翻的"},{"en":"turned upside down","cn":"翻转的﹐倒置的"}]},"media":{"uk":"media/ldoce/hwd/bre/b/brelasdeupturned.mp3","us":"media/ldoce/hwd/ame/a/upturned.mp3"},"examples":[{"en":"She looked down at the sea of upturned faces.","cn":"她俯视着一大片仰起的脸孔。"},{"en":"She sat on an upturned box.","cn":"她坐在一个倒放的箱子上。"}],"oxford":{"phon":"ˌʌpˈtɜːnd","pos":"adjective","senses":[{"en":"pointing or facing upwards","cn":"向上翘的；面朝上的","ex":{"en":"an upturned nose (= that curves upwards at the end)","cn":"翘鼻子"}},{"en":"turned into a position in which the top part is where the bottom part normally is","cn":"颠倒的；翻转的；倒着的","ex":{"en":"She sat on an upturned box.","cn":"她坐在一个倒放的箱子上。"}}]}},"upper-class":{"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"belonging to the class of people who originally had most of the money and power, especially families that own a lot of land","cn":""},{"en":"the people who belong to families that own a lot of land, and used to have a lot of power, and have special titles before their names, like 'Lord' or 'Lady' - used especially when you are talking about the past","cn":""},{"en":"having a high position in society that has special, and usually unfair, advantages such as power, money and the best education","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/5/brelasdeupper_class.mp3","us":"media/ldoce/hwd/ame/d/upper_class.mp3"},"oxford":{"phon":"ði ˌʌpə ˈklɑːs","pos":"adjective","senses":[{"en":"belonging to or typical of groups of people that are considered to have the highest social status and that have more money and/or power than other people in society","cn":"上流社会的；上层阶级的","ex":{"en":"Her family is very upper class.","cn":"她家世显赫。"}}]}},"upstage":{"collins":{"senses":[{"pos":"ADV 副词","cn":"在舞台后部；朝舞台后面","en":"When an actor is upstage or moves upstage, he or she is or moves towards the back part of the stage.","ex":{"en":"Upstage and right of centre, Robert Morris stands with his back to the audience","cn":"舞台后方偏右处，罗伯特·莫里斯背对观众站着。"}},{"pos":"VERB 动词","cn":"使相形见绌；抢…的风头","en":"If someone upstages you, they draw attention away from you by being more attractive or interesting.","ex":{"en":"He had a younger brother who always publicly upstaged him","cn":"他有一个弟弟，总是公然抢他的风头。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to do something that takes people’s attention away from someone else who is more important","cn":"抢…的风头﹐抢…的镜头"},{"en":"towards the back of the stage in a theatre","cn":"朝着舞台后方"}]},"vocab":{"pos":"adv v n adj","senses":[{"en":"To upstage is to steal the show. If you try to upstage your \"Grease\" costar, you'll attempt to pull the audience's attention away from him and onto you at the back of the stage doing cartwheels."}]},"media":{"uk":"media/ldoce/hwd/bre/a/upstage_adv0205.mp3","us":"media/ldoce/hwd/ame/b/upstage1.mp3"},"examples":[{"en":"She was furious at being upstaged by her younger sister.","cn":"她被妹妹抢去风头，感到气愤不已。"},{"en":"All the big-name stars were upstaged by 12-year-old Katy Rochford.","cn":"所有的大明星都被12岁的凯蒂·罗奇福德抢去了风头。"}],"oxford":{"phon":"ˌʌpˈsteɪdʒ","pos":"adverb, adjective","senses":[{"en":"at or towards the back of the stage in a theatre","cn":"在（或向）舞台后部（的）"},{"en":"to say or do something that makes people notice you more than the person that they should be interested in","cn":"抢…的镜头；把对…的注意吸引过来","ex":{"en":"She was furious at being upstaged by her younger sister.","cn":"她被妹妹抢去风头，感到气愤不已。"},"pos":"verb"}]}},"upbraid":{"collins":{"senses":[{"pos":"VERB 动词","cn":"责难；非难；责骂","en":"If you upbraid someone, you tell them that they have done something wrong and criticize them for doing it.","ex":{"en":"His mother summoned him, upbraided him, wept and prayed","cn":"他母亲把他叫到跟前训斥了一番，又哭哭啼啼地向上帝祷告。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to tell someone angrily that they have done something wrong","cn":"责骂﹐申斥﹐训斥"}]},"vocab":{"pos":"v","senses":[{"en":"No, upbraid isn’t what girls get done at a salon before prom. When you upbraid people, you scold them, tell them off and criticize them. (You could, however, upbraid your stylist after a bad haircut.)"}]},"media":{"uk":"media/ldoce/hwd/bre/2/ld44upbraid.mp3","us":"media/ldoce/hwd/ame/2/ld44upbraid.mp3"},"oxford":{"phon":"ʌpˈbreɪd","pos":"verb","senses":[{"en":"to criticize somebody or speak angrily to them because you do not approve of something that they have said or done","cn":"申斥；训斥；责骂"}]}}});
